import { Order } from './types';

const CURSOR_SEPARATOR = '|';

interface CursorKey {
  createdAt: string;
  id: string;
}

function compareCursorKeys(a: { createdAt: string; id: string }, b: { createdAt: string; id: string }): number {
  if (a.createdAt < b.createdAt) return -1;
  if (a.createdAt > b.createdAt) return 1;
  if (a.id < b.id) return -1;
  if (a.id > b.id) return 1;
  return 0;
}

export function cursorOf(order: { createdAt: string; id: string }): string {
  return order.createdAt + CURSOR_SEPARATOR + order.id;
}

export function parseCursor(cursor: string): CursorKey {
  if (typeof cursor !== 'string') throw new Error('invalid request');
  const parts = cursor.split(CURSOR_SEPARATOR);
  if (parts.length !== 2 || !parts[0] || !parts[1]) throw new Error('invalid request');
  return { createdAt: parts[0], id: parts[1] };
}

export class OrderRepository {
  constructor(private readonly rows: Order[]) {}

  list(tenant: string, cursor?: string): Order[] {
    const matching = this.rows.filter(row => row.tenant === tenant);
    matching.sort((a, b) => compareCursorKeys(a, b));
    if (cursor === undefined) return matching;
    const key = parseCursor(cursor);
    return matching.filter(row => compareCursorKeys(row, key) > 0);
  }
}
```

